import React, { forwardRef } from 'react';
import { useIntl } from 'react-intl';

import { OpenWithIcon } from '@dynatrace/strato-icons';
import type { IntentPayload } from '@dynatrace-sdk/navigation';

import { useIntentButton } from './useIntentButton.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { type ButtonOwnProps, Button } from '../button/Button.js';

//#region Typings
export interface IntentButtonPropsBase
  extends Omit<ButtonOwnProps, 'loading' | 'type'>,
    AriaLabelingProps,
    DOMProps,
    StylingProps,
    DataTestId {
  /** Intent payload passed between apps.*/
  payload: IntentPayload;

  /** Intended for setting a custom button label.
   * @defaultValue `Open with`
   */
  children?: string;

  /**
   * If true, hide the label and show only the icon.
   */
  iconOnly?: boolean;
}

/** Props for recommending an app to receive the intent. Either both poperties or none of them needs to be specified. */
export type IntentButtonRecommendAppProps =
  | {
      appId?: never;
      intentId?: never;
    }
  | {
      /**
       * ID of the app that will be launched to handle the intent.
       */
      appId: string;

      /**
       * ID of the action that will be passed to the app.
       */
      intentId: string;
    };

export type IntentButtonProps = IntentButtonPropsBase &
  IntentButtonRecommendAppProps;

//#endregion

/**
 * The `IntentButton` is a dedicated button component for sending
 * {@link https://developer.dynatrace.com/develop/intents/ | intents}.
 * It takes care of opening the intent dialog. An `IntentButton` only works
 * in the AppShell context.
 */
export const IntentButton = /* @__PURE__ */ forwardRef<
  HTMLAnchorElement,
  IntentButtonProps
>((props, forwardedRef) => {
  const intl = useIntl();
  const {
    children,
    payload,
    appId,
    intentId,
    iconOnly,
    disabled,
    onClick: onClickProp,
    'aria-label': ariaLabel,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  }: IntentButtonProps = props;

  const defaultLabel = intl.formatMessage({
    description: 'Intent button open label',
    defaultMessage: 'Open with',
    id: 'JQOGuaGgqJObmSY1',
  });

  const label = children?.trim() || defaultLabel;

  const intentButtonProps = useIntentButton(
    payload,
    appId,
    intentId,
    onClickProp,
  );

  // polymorph it back to a button in case it's disabled.
  // Keep the button focusable if disabled for better screen reader support.
  if (disabled) {
    return (
      <Button
        disabled
        data-testid={dataTestId}
        aria-label={ariaLabel ?? label}
        className={consumerClassName}
        style={consumerStyle}
        {...remainingProps}
      >
        <Button.Suffix>
          <OpenWithIcon />
        </Button.Suffix>
        {!iconOnly && label}
      </Button>
    );
  }

  return (
    <Button
      as="a"
      ref={forwardedRef}
      data-testid={dataTestId}
      aria-label={ariaLabel ?? label}
      className={consumerClassName}
      style={consumerStyle}
      {...remainingProps}
      {...intentButtonProps}
    >
      <Button.Suffix>
        <OpenWithIcon />
      </Button.Suffix>
      {!iconOnly && label}
    </Button>
  );
});

(IntentButton as typeof IntentButton & { displayName: string }).displayName =
  'IntentButton';
